package com.gbkhealthcare.billing;

import com.gbkhealthcare.auth.*;import com.gbkhealthcare.patient.*;import org.junit.jupiter.api.*;import org.mockito.ArgumentCaptor;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class BillingServiceTest {
 StaffAccessService staff;AdminAccountRepository admins;PatientVisitRepository visits;BillableServiceRepository services;BillableServicePriceRepository prices;BillingInvoiceRepository invoices;BillingInvoiceLineRepository lines;BillingPaymentRepository payments;BillingRefundRepository refunds;BillingAdjustmentRepository adjustments;BillingAuditEventRepository audit;BillingService billing;StaffAccount actor;PatientVisit visit;Patient patient;Jwt jwt;
 @BeforeEach void setup(){staff=mock(StaffAccessService.class);admins=mock(AdminAccountRepository.class);visits=mock(PatientVisitRepository.class);services=mock(BillableServiceRepository.class);prices=mock(BillableServicePriceRepository.class);invoices=mock(BillingInvoiceRepository.class);lines=mock(BillingInvoiceLineRepository.class);payments=mock(BillingPaymentRepository.class);refunds=mock(BillingRefundRepository.class);adjustments=mock(BillingAdjustmentRepository.class);audit=mock(BillingAuditEventRepository.class);billing=new BillingService(staff,admins,visits,services,prices,invoices,lines,payments,refunds,adjustments,audit);actor=mock(StaffAccount.class);when(actor.getId()).thenReturn(12L);when(actor.getEmail()).thenReturn("checkout@example.test");when(staff.requireRole(any(),eq(StaffRole.CHECKOUT))).thenReturn(actor);visit=mock(PatientVisit.class);patient=mock(Patient.class);when(patient.getId()).thenReturn(4L);when(patient.getFullName()).thenReturn("Test Patient");when(visit.getId()).thenReturn(25L);when(visit.getPatient()).thenReturn(patient);when(visit.getConsultationStatus()).thenReturn("SIGNED");when(visit.getEncounterStatus()).thenReturn("CONSULTATION_SIGNED");jwt=Jwt.withTokenValue("test").header("alg","none").subject("checkout@example.test").build();}
 @Test void createsDraftWithCurrentPriceSnapshotAndSafeInvoiceNumber(){when(visits.findByIdForBillingUpdate(25L)).thenReturn(Optional.of(visit));when(invoices.findFirstByPatientVisit_IdAndStatusNot(25L,BillingInvoice.Status.VOID)).thenReturn(Optional.empty());BillableService service=mock(BillableService.class);when(service.getId()).thenReturn(8L);when(service.getCode()).thenReturn("CONSULT");when(service.getName()).thenReturn("Consultation");when(service.isActive()).thenReturn(true);BillableServicePrice price=new BillableServicePrice(service,3,new BigDecimal("125.00"),new BigDecimal("5.00"),2L,LocalDateTime.now());when(services.findById(8L)).thenReturn(Optional.of(service));when(prices.findTopByService_IdOrderByVersionDesc(8L)).thenReturn(Optional.of(price));when(invoices.save(any())).thenAnswer(i->i.getArgument(0));InvoiceResponse response=billing.createInvoice(jwt,25L,new InvoiceCreateRequest(List.of(new InvoiceLineRequest(8L,new BigDecimal("2"))),BigDecimal.ZERO));assertTrue(response.invoiceNumber().matches("GBK-[A-F0-9]{32}"));assertEquals("DRAFT",response.status().name());ArgumentCaptor<BillingInvoice> captor=ArgumentCaptor.forClass(BillingInvoice.class);verify(invoices).save(captor.capture());BillingInvoice invoice=captor.getValue();assertEquals(new BigDecimal("250.00"),invoice.getSubtotal());assertEquals(new BigDecimal("12.50"),invoice.getTaxAmount());assertEquals(1,invoice.getLines().size());assertEquals(new BigDecimal("125.00"),invoice.getLines().get(0).getUnitPriceSnapshot());verify(audit).save(argThat(e->e.getActionType().equals("INVOICE_CREATED")));}
 @Test void activeInvoicePreventsDuplicateForEncounter(){when(visits.findByIdForBillingUpdate(25L)).thenReturn(Optional.of(visit));when(invoices.findFirstByPatientVisit_IdAndStatusNot(25L,BillingInvoice.Status.VOID)).thenReturn(Optional.of(mock(BillingInvoice.class)));assertThrows(ResponseStatusException.class,()->billing.createInvoice(jwt,25L,new InvoiceCreateRequest(List.of(new InvoiceLineRequest(8L,BigDecimal.ONE)),BigDecimal.ZERO)));verifyNoInteractions(services);}
 @Test void unauthorizedRoleIsRejectedByStaffAccess(){when(staff.requireRole(any(),eq(StaffRole.CHECKOUT))).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->billing.outstanding(jwt));verifyNoInteractions(invoices);}
 @Test void paymentCannotExceedOutstandingBalance(){BillingInvoice invoice=mock(BillingInvoice.class);when(invoice.getId()).thenReturn(3L);when(invoice.getStatus()).thenReturn(BillingInvoice.Status.ISSUED);when(invoice.getOutstandingAmount()).thenReturn(new BigDecimal("25.00"));when(invoices.findByIdForUpdate(3L)).thenReturn(Optional.of(invoice));assertThrows(ResponseStatusException.class,()->billing.recordPayment(jwt,3L,new PaymentRequest(new BigDecimal("25.01"),BillingPayment.Method.CASH,null,null)));verifyNoInteractions(payments);}
 @Test void paymentReferenceRejectsCardAndCredentialData(){BillingInvoice invoice=mock(BillingInvoice.class);when(invoice.getId()).thenReturn(3L);when(invoice.getStatus()).thenReturn(BillingInvoice.Status.ISSUED);when(invoice.getOutstandingAmount()).thenReturn(new BigDecimal("50.00"));when(invoices.findByIdForUpdate(3L)).thenReturn(Optional.of(invoice));assertThrows(ResponseStatusException.class,()->billing.recordPayment(jwt,3L,new PaymentRequest(new BigDecimal("10.00"),BillingPayment.Method.CARD,null,"CVV 123")));verifyNoInteractions(payments);}
 @Test void multiplePartialPaymentsAccumulateAndAudit(){BillingInvoice invoice=mock(BillingInvoice.class);when(invoice.getId()).thenReturn(3L);when(invoice.getStatus()).thenReturn(BillingInvoice.Status.ISSUED);when(invoice.getOutstandingAmount()).thenReturn(new BigDecimal("100.00"));when(invoice.getPatientVisit()).thenReturn(visit);when(invoices.findByIdForUpdate(3L)).thenReturn(Optional.of(invoice));when(invoices.save(any())).thenReturn(invoice);List<BillingPayment> recorded=new ArrayList<>();when(payments.save(any())).thenAnswer(call->{BillingPayment p=call.getArgument(0);recorded.add(p);return p;});when(payments.findAllByInvoice_IdOrderByPaidAtAsc(3L)).thenAnswer(call->List.copyOf(recorded));when(refunds.findAllByPayment_IdOrderByRefundedAtAsc(any())).thenReturn(List.of());when(adjustments.findAllByInvoice_IdOrderByCreatedAtAsc(3L)).thenReturn(List.of());billing.recordPayment(jwt,3L,new PaymentRequest(new BigDecimal("30.00"),BillingPayment.Method.CASH,null,null));billing.recordPayment(jwt,3L,new PaymentRequest(new BigDecimal("25.00"),BillingPayment.Method.UPI,null,"upi-ref"));ArgumentCaptor<BigDecimal> paidCaptor=ArgumentCaptor.forClass(BigDecimal.class);verify(invoice,times(2)).updateBalances(paidCaptor.capture(),eq(new BigDecimal("0.00")),any(LocalDateTime.class));assertEquals(new BigDecimal("55.00"),paidCaptor.getAllValues().get(1));verify(audit,times(2)).save(any(BillingAuditEvent.class));}
 @Test void refundCannotExceedUnrefundedPaymentAmount(){BillingInvoice invoice=mock(BillingInvoice.class);when(invoice.getId()).thenReturn(3L);when(invoices.findByIdForUpdate(3L)).thenReturn(Optional.of(invoice));BillingPayment payment=new BillingPayment(invoice,"REC-1",new BigDecimal("20.00"),BillingPayment.Method.CASH,"pay-ref",12L,LocalDateTime.now());when(payments.findById(6L)).thenReturn(Optional.of(payment));when(refunds.findAllByPayment_IdOrderByRefundedAtAsc(6L)).thenReturn(List.of(new BillingRefund(payment,new BigDecimal("15.00"),"Previous",null,12L,LocalDateTime.now())));assertThrows(ResponseStatusException.class,()->billing.refund(jwt,3L,6L,new RefundRequest(new BigDecimal("5.01"),"Over limit",null)));verify(refunds,never()).save(any());}
 @Test void invoiceIssueAndPaymentEntitiesKeepAppendOnlyState(){BillingInvoice invoice=new BillingInvoice(visit,"GBK-TEST",new BigDecimal("50.00"),BigDecimal.ZERO,BigDecimal.ZERO,12L,LocalDateTime.now());invoice.issue();assertEquals(BillingInvoice.Status.ISSUED,invoice.getStatus());assertThrows(IllegalStateException.class,invoice::issue);}
 @Test void outstandingBalanceTracksPartialAndFullPayments(){BillingInvoice invoice=new BillingInvoice(visit,"GBK-BALANCE",new BigDecimal("100.00"),BigDecimal.ZERO,BigDecimal.ZERO,12L,LocalDateTime.now());invoice.issue();invoice.updateBalances(new BigDecimal("35.00"),new BigDecimal("0.00"),LocalDateTime.now());assertEquals(new BigDecimal("35.00"),invoice.getPaidAmount());assertEquals(new BigDecimal("65.00"),invoice.getOutstandingAmount());assertEquals(BillingInvoice.Status.PARTIALLY_PAID,invoice.getStatus());invoice.updateBalances(new BigDecimal("100.00"),new BigDecimal("0.00"),LocalDateTime.now());assertEquals(BigDecimal.ZERO.setScale(2),invoice.getOutstandingAmount());assertEquals(BillingInvoice.Status.PAID,invoice.getStatus());}
}
